use std::{sync::Arc, time::Duration};
use async_trait::async_trait;
use futures_core::stream::BoxStream;
use paigasus_helikon_core::*;
use paigasus_helikon_runtime_tokio::TokioRunner;

/// Mimics a real provider: stream a tool call, then wait; on cancel end the stream with no Finish.
struct ProviderLike;
#[async_trait]
impl Model for ProviderLike {
    async fn invoke(&self, _r: ModelRequest, cancel: CancellationToken)
        -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
        Ok(Box::pin(async_stream::stream! {
            yield Ok(ModelEvent::ToolCallDelta { call_id: "c1".into(), name: Some("search".into()), args_delta: "{}".into() });
            tokio::select! { biased; _ = cancel.cancelled() => return, _ = std::future::pending::<()>() => {} }
        }))
    }
    fn capabilities(&self) -> ModelCapabilities { ModelCapabilities::default() }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() {
    let cancel = CancellationToken::new();
    let agent = LlmAgent::builder::<()>().name("root").shared_model(Arc::new(ProviderLike)).build();
    let ctx = RunContext::ephemeral(()).with_cancel(cancel.clone());
    let c2 = cancel.clone();
    tokio::spawn(async move { tokio::time::sleep(Duration::from_millis(50)).await; c2.cancel(); });
    let res = TokioRunner.run(&agent, ctx, AgentInput::from_user_text("go"), RunConfig::default()).await;
    match res { Err(e) => println!("RESULT Err: {e:?}"), Ok(r) => println!("RESULT Ok: stop={:?}", r.stop_reason) }
}

